statement:
`piles[i]` is the number of coins in pile `i`, and the number of piles is a multiple of 3. You, Alice and Bob share them out in rounds until no pile is left. In each round:

- you pick any three of the remaining piles (they need not be next to each other);
- Alice takes the largest of the three;
- you take the second largest;
- Bob takes the one that is left.

Return the most coins you can collect in total by choosing the triples well.

validator:
function validate([piles]) {
  if (!Array.isArray(piles) || piles.length < 3 || piles.length > 100000) return 'piles needs 3 to 10^5 values.';
  if (piles.length % 3 !== 0) return 'The number of piles must be a multiple of 3.';
  if (piles.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each pile holds an integer from 1 to 10^4 coins.';
  return null;
}

reference:
function maxCoins(piles) {
  piles.sort((a, b) => a - b);
  const rounds = piles.length / 3;
  let total = 0;

  for (let i = rounds; i < piles.length; i += 2) {
    total += piles[i];
  }
  return total;
}

