function maxCoins(piles) {
  // Try every way to split the piles into triples; you get the middle of each.
  const used = piles.map(() => false);
  const search = () => {
    const first = used.indexOf(false);
    if (first === -1) return 0;
    used[first] = true;
    let best = -Infinity;
    for (let b = first + 1; b < piles.length; b++) {
      if (used[b]) continue;
      used[b] = true;
      for (let c = b + 1; c < piles.length; c++) {
        if (used[c]) continue;
        used[c] = true;
        const triple = [piles[first], piles[b], piles[c]].sort((x, y) => x - y);
        best = Math.max(best, triple[1] + search());
        used[c] = false;
      }
      used[b] = false;
    }
    used[first] = false;
    return best;
  };
  return search();
}

