function generate(rand, size) {
  const large = size === 'large';
  const rounds = large ? 500 + Math.floor(rand() * 167) : 1 + Math.floor(rand() * 4);
  const top = large || rand() < 0.3 ? 10000 : 1 + Math.floor(rand() * 10);
  return [Array.from({ length: 3 * rounds }, () => 1 + Math.floor(rand() * top))];
}
